plan = {"A": ("M1", 0, 3), "B": ("M1", 3, 5),
        "C": ("M1", 4, 8), "D": ("M2", 0, 4)}  # (기계, 시작, 끝)
due = {"A": 3, "B": 5, "C": 7, "D": 6}

def check(plan, due):
    errs = []
    rows = {}
    for job, (mc, s, e) in plan.items():
        rows.setdefault(mc, []).append((s, e, job))
        if e > due[job]:
            errs.append(f"{job} 납기 {e - due[job]}칸 늦음")
    for mc, lst in rows.items():
        lst.sort()
        for (s1, e1, j1), (s2, e2, j2) in zip(lst, lst[1:]):
            if s2 < e1:
                errs.append(f"{mc} 겹침 {j1}-{j2}")
    return errs

print(check(plan, due))

